const j = $json;
const id = j.lead_id ?? j.id ?? (j.body && (j.body.lead_id ?? j.body.id)) ?? '';
return [{ json: { lead_id: String(id) } }];

const leadId = $('Resolve Lead Id').first().json.lead_id;
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(leadId)) throw new Error('Invalid UUID lead ID');
const out = $json.output ?? $json;
const lead = $('Load Lead').first().json;
const organization = String(out.organisation ?? out.organization ?? lead.raw_payload?.organization ?? '').trim() || null;
const prospect = {
  lead_id: leadId,
  sector: typeof out.sector === 'string' && out.sector.trim() ? out.sector.trim() : 'unknown',
  revenue_estimate: out.revenue_estimate ?? null,
  past_projects: Array.isArray(out.past_projects) ? out.past_projects : [],
  partners: Array.isArray(out.partners) ? out.partners : [],
  domain_needs: Array.isArray(out.domain_needs) ? out.domain_needs : [],
  partial: true,
  raw: { ...out, organisation: organization, sources: [] },
};
return [{ json: { prospect_json: JSON.stringify(prospect) } }];

const src = $json ?? {};
let leadId = '';
try { leadId = $('Resolve Lead Id').first().json.lead_id; } catch (e) {}
if (!leadId) { try { leadId = src.lead_id ?? src.id ?? ''; } catch (e) {} }
const errRaw = src.error ?? src.message ?? src;
const errText = typeof errRaw === 'string' ? errRaw : (errRaw.message ?? JSON.stringify(errRaw));
return [{ json: { error_json: JSON.stringify({ lead_id: String(leadId ?? ''), error: String(errText).slice(0, 500) }) } }];
